"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0739-01-01:0":{"b": ["Alfonso I (yerno de Pelayo) sube al trono (739-757).", "9df77d42"], "d": ["Alfonso I (yerno de Pelayo) sube al trono (739-757).", "9df77d42"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0757-05-25:0":{"b": ["Los jariyíes sufríes se apoderan de Kairuán", "e215c08e"], "d": ["Tras el colapso del gobierno omeya de Ifriqiya, Kairuán fue tomada en 140 (757) a los jariyíes sufríes por Âsım al-Warfajumi.", "a8302c5a"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0791-01-01:0":{"b": ["Alfonso II sube al trono (791/792-842).", "f0b5c786"], "d": ["Alfonso II sube al trono (791/792-842).", "f0b5c786"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0793-04-18:0":{"b": ["Tras Idris I, Idris II pasa a gobernar (177, 793).", "b10b3d2f"], "d": ["Tras Idris I, Idris II pasa a gobernar (177, 793).", "b10b3d2f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0810-01-01:0":{"b": ["Ibrahim b. Aglab sofoca la rebelión de Imrán b. Mücâlid.", "7ec4ce44"], "d": ["Ibrahim b. Aglab sofoca la rebelión de Imrán b. Mücâlid.", "7ec4ce44"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0810-01-01:1":{"b": ["Alfonso II traslada la capital de Cangas a Oviedo (hacia 810).", "6eccb0ae"], "d": ["Alfonso II traslada la capital de Cangas a Oviedo (hacia 810).", "6eccb0ae"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0812-01-01:0":{"b": ["Ibrahim b. Aglab muere sin haber podido someter al jefe ibadí Abdülvehhâb, que sitiaba Trípoli; su hijo Abdullah se convierte en emir.", "192bb140"], "d": ["Ibrahim b. Aglab muere sin haber podido someter al jefe ibadí Abdülvehhâb, que sitiaba Trípoli; su hijo Abdullah se convierte en emir.", "192bb140"]},
