"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0862-03-11:0":{"b": ["Murió Tâhir II; en su lugar fue nombrado gobernador Muhammed b. Tâhir (248/862).", "22af070e"], "d": ["Murió Tâhir II; en su lugar fue nombrado gobernador Muhammed b. Tâhir (248/862).", "22af070e"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0876-09-24:0":{"b": ["Murió İbnü's-Sakıyye; su hijo Muhammed subió al trono (263, 876-77).", "89f473df"], "d": ["Murió İbnü's-Sakıyye; su hijo Muhammed subió al trono (263, 876-77).", "89f473df"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0883-07-11:0":{"b": ["Murió Muhammed; su tío Elyesa' II accedió al emirato (270, 883).", "1a21eeb6"], "d": ["Murió Muhammed; su tío Elyesa' II accedió al emirato (270, 883).", "1a21eeb6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0903-07-01:0":{"b": ["Los qarmatas sitiaron Damasco; el líder Sâhibünnâka Yahyâ fue muerto durante el asedio", "9b876cc8"], "d": ["Yahyâ, conocido como Sâhibünnâka, uno de los hijos de Zikreveyh b. Mihreveyh, fue muerto durante el asedio de Damasco en sha'ban de 290 (julio de 903); su hermano Sâhibüşşâme ocupó su lugar y, tras un ataque fallido contra Alepo, se apoderó de Hama, Homs, Ma'arrat al-Nu'man y Baalbek.", "9980a87c"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0906-01-01:0":{"b": ["El dâî qarmata Ebû Gānim entró en Kufa tras saquear Bosra, Tiberíades y Hit; fue expulsado en poco tiempo", "7b175ddd"], "d": ["Ebû Gānim Abdullah b. Saîd, enviado por Zikreveyh para revivir el qarmatismo entre los Banu Kalb, y sus hombres saquearon localidades como Bosra, Ezriât, Tiberíades y Hit y atacaron Damasco; al no tener éxito entraron en Kufa, pero poco después fueron expulsados de la ciudad (293/906).", "e62c81d1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0911-01-01:0":{"b": ["El Estado uigur de Turfán se hizo independiente", "d48689ad"], "d": ["El Estado uigur de Turfán se hizo independiente", "d48689ad"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0913-01-01:0":{"b": ["Ebû Saîd al-Cennâbî fue muerto en un atentado organizado por Ubeydullah al-Mahdi (301); sus hijos continuaron el Estado.", "dd507fc0"], "d": ["Ebû Saîd al-Cennâbî fue muerto en un atentado organizado por Ubeydullah al-Mahdi (301); sus hijos continuaron el Estado.", "dd507fc0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0931-01-24:0":{"b": ["Ebû Tâhir cedió el gobierno de Bahréin a un persa que presentó como mahdi; el nuevo mahdi fue muerto ochenta días después", "1816f4a5"], "d": ["Ebû Tâhir al-Cennâbî, que se había apoderado de Omán (318/930), cedió al año siguiente el gobierno de Bahréin a un persa traído de Isfahán y presentado al pueblo como mahdi. El persa, que se presentó como descendiente de los antiguos cosroes de Persia y reformador de la religión persa y expuso ideas contrarias a los árabes, fue muerto por Ebû Tâhir ochenta días después de su nombramiento; esto causó gran asombro y desbandada entre los qarmatas de Bahréin.", "919b72ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0935-01-01:0":{"b": ["Merdâvîc es muerto en Isfahán por soldados turcos; le sucede su hermano Veşmgîr (323/935).", "11355262"], "d": ["Merdâvîc es muerto en Isfahán por soldados turcos; le sucede su hermano Veşmgîr (323/935).", "11355262"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0944-01-01:0":{"b": ["Murió Ebû Tâhir (332); sus hermanos siguieron una política pacífica frente a los abasíes.", "4b409f1d"], "d": ["Murió Ebû Tâhir (332); sus hermanos siguieron una política pacífica frente a los abasíes.", "4b409f1d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0957-12-01:0":{"b": ["Merzübân muere en ramadán de 346 (diciembre de 957); le sucede Cüstân.", "90c5eee8"], "d": ["Merzübân muere en ramadán de 346 (diciembre de 957); le sucede Cüstân.", "90c5eee8"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0962-01-01:0":{"b": ["Los uigures de Turfán (Kao-ch'ang) enviaron a China su primera delegación comercial de 42 personas.", "f51160fd"], "d": ["Los uigures de Turfán (Kao-ch'ang) enviaron a China su primera delegación comercial de 42 personas.", "f51160fd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0966-01-01:0":{"b": ["İbrâhim es derrotado por Vehsûdân y se refugia en Rüknüddevle (355/966).", "e5df11cd"], "d": ["İbrâhim es derrotado por Vehsûdân y se refugia en Rüknüddevle (355/966).", "e5df11cd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0967-01-01:0":{"b": ["Veşmgîr muere durante una cacería (357/967).", "68f9525b"], "d": ["Veşmgîr muere durante una cacería (357/967).", "68f9525b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0972-07-01:0":{"b": ["Hasan al-A'sam ocupó de nuevo Ramla y derrotó a un poderoso ejército fatimí", "c3b5ad80"], "d": ["El líder qarmata Hasan al-A'sam ocupó de nuevo Ramla en ramadán de 361 (julio de 972) y derrotó a un poderoso ejército fatimí; un año después atacó Egipto por tierra y por mar y volvió a sitiar El Cairo, pero fue derrotado por al-Aziz Billah.", "f629e2e1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0981-01-01:0":{"b": ["El embajador chino Wang Yente comenzó a recorrer las tierras de los uigures (981-984); su informe es la fuente principal de la cultura uigur de Turfán.", "478d801b"], "d": ["El embajador chino Wang Yente comenzó a recorrer las tierras de los uigures (981-984); su informe es la fuente principal de la cultura uigur de Turfán.", "478d801b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-01-01:0":{"b": ["Fracasó el ejército enviado por Mansûr b. Bulukkîn a Fez y Sijilmasa (374, 985).", "85a5064b"], "d": ["Fracasó el ejército enviado por Mansûr b. Bulukkîn a Fez y Sijilmasa (374, 985).", "85a5064b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-05-24:0":{"b": ["Los qarmatas de Bahréin ocuparon Kufa dos años después de Basora; no pudieron mantenerse frente a los buyíes y se retiraron", "4b76d4b0"], "d": ["Los qarmatas de Bahréin, que querían mostrar su fuerza en el sur de Irak tras la muerte del buyí Adudüddevle (372/983), atacaron Basora en 373 (983-84) y la hicieron tributaria, y dos años después ocuparon Kufa; pero no pudieron mantenerse frente a los buyíes y se retiraron, y no volvieron a tener voz en Irak.", "0451dba6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0991-01-01:0":{"b": ["Ebü'l-Feth Muhammed b. Annâz comenzó a reinar en Hulvân", "b1809519"], "d": ["Ebü'l-Feth Muhammed b. Annâz comenzó a reinar en Hulvân", "b1809519"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0998-08-01:0":{"b": ["Kābûs, que regresó del exilio samánida, derrota a Mecdüddevle y recupera el trono ziyárida de Gorgán (sha'ban de 388 / agosto de 998).", "1cefb125"], "d": ["Kābûs, que regresó del exilio samánida, derrota a Mecdüddevle y recupera el trono ziyárida de Gorgán (sha'ban de 388 / agosto de 998).", "1cefb125"]},
