"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1041-09-01:0":{"b": ["Alâüddevle Muhammed muere a su regreso de Dinawar (muharram de 433 / septiembre de 1041).", "555e6b13"], "d": ["Alâüddevle Muhammed muere a su regreso de Dinawar (muharram de 433 / septiembre de 1041).", "555e6b13"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1046-04-01:0":{"b": ["Ebü'ş-Şevk muere en Sîrvân (ramadán de 437 / abril de 1046).", "6a0a6d89"], "d": ["Ebü'ş-Şevk muere en Sîrvân (ramadán de 437 / abril de 1046).", "6a0a6d89"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1046-08-01:0":{"b": ["El annazí Sa'dî hizo pronunciar la jutba en Hulvân en nombre de İbrâhim Yinal", "5cbe7ebb"], "d": ["Tras la muerte de Ebü'ş-Şevk (abril de 1046), Sa'dî b. Ebü'ş-Şevk, enemistado con su tío Mühelhil, se unió con una comunidad de la tribu Şâzencân al comandante selyúcida İbrâhim Yinal e hizo pronunciar la jutba en su nombre en Hulvân (agosto de 1046); así el país de los annazíes quedó abierto a la influencia selyúcida.", "bf9a2a58"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1047-01-01:0":{"b": ["Ali al-Suleyhî se rebeló al tomar Cebelimesâr; se fundó la dinastía sulayhí", "e8ea1532"], "d": ["Ali al-Suleyhî se rebeló al tomar Cebelimesâr; se fundó la dinastía sulayhí", "e8ea1532"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1050-01-01:0":{"b": ["Mühelhil se sometió a Tuğrul Bey; Tuğrul reasentó a los annazíes en Sîrvân, Dakūkā, Şehrizor y Samgan", "57846ea4"], "d": ["Mühelhil se sometió a Tuğrul Bey; Tuğrul reasentó a los annazíes en Sîrvân, Dakūkā, Şehrizor y Samgan", "57846ea4"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1053-01-01:0":{"b": ["Sa'dî derrota y captura a Mühelhil.", "94793e35"], "d": ["Sa'dî derrota y captura a Mühelhil.", "94793e35"]},
